var e={configEditor:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Leia a configuração ativa da sua impressora direto do Moonraker - cada arquivo, analisado em seções e parâmetros, com os problemas estruturais sinalizados. Somente leitura por enquanto; a edição guiada chega em breve.`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Ajuda`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Sobre o Editor de Configuração`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Fechar`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Como usar`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Escolha um arquivo de configuração no menu - printer.cfg vem selecionado por padrão.`}},{t:0,b:{t:2,i:[{t:3}],s:`Navegue pelas seções; clique em uma para expandir seus parâmetros.`}},{t:0,b:{t:2,i:[{t:3}],s:`Confira o aviso de Validação para problemas estruturais, como uma seção duplicada.`}},{t:0,b:{t:2,i:[{t:3}],s:`Mude para Bruto para ler o texto exato do arquivo.`}}],topics:{sections:{title:{t:0,b:{t:2,i:[{t:3}],s:`Seções e parâmetros`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Uma configuração do Klipper é uma lista de blocos [section], cada um contendo parâmetros no formato chave: valor. Este widget analisa cada seção - incluindo as com nome como [tmc2209 stepper_x] - e lista seus parâmetros com o valor e qualquer comentário em linha. Valores de várias linhas (como o gcode: de uma macro) são mantidos intactos.`}}},includes:{title:{t:0,b:{t:2,i:[{t:3}],s:`Arquivos incluídos`}},body:{t:0,b:{t:2,i:[{t:3}],s:`O printer.cfg costuma puxar outros arquivos com [include other.cfg] (ou um glob como [include configs/*.cfg]). Cada inclusão aparece como sua própria entrada; escolha o arquivo incluído no menu para inspecionar o que ele define.`}}},validation:{title:{t:0,b:{t:2,i:[{t:3}],s:`Validação`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Após a análise, a configuração é verificada quanto a problemas estruturais que estão errados independentemente do tipo da seção - um cabeçalho de seção duplicado, um nome de seção vazio ou um parâmetro fora de qualquer seção. Eles aparecem no aviso de Validação; não alteram o seu arquivo.`}}},saveConfig:{title:{t:0,b:{t:2,i:[{t:3}],s:`O bloco SAVE_CONFIG`}},body:{t:0,b:{t:2,i:[{t:3}],s:`O Klipper acrescenta um bloco gerado automaticamente no fim do printer.cfg (após o marcador #*#) quando você executa SAVE_CONFIG - resultados de calibração como PID e offsets de Z. Ele é exibido, mas sinalizado como salvo automaticamente, e fica fora da contagem de seções editáveis porque você não deve editá-lo à mão.`}}},readonly:{title:{t:0,b:{t:2,i:[{t:3}],s:`Somente leitura (por enquanto)`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Esta primeira versão apenas lê e exibe a configuração - nada é gravado na impressora. A edição guiada com confirmação (com backup automático antes de qualquer gravação e reinício em seguida) chega em uma atualização futura.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glossário`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{section:{term:{t:0,b:{t:2,i:[{t:3}],s:`Seção`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Um bloco [header] que agrupa configurações relacionadas, por exemplo [stepper_x] ou [extruder].`}}},parameter:{term:{t:0,b:{t:2,i:[{t:3}],s:`Parâmetro`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Uma linha chave: valor (ou chave = valor) dentro de uma seção, opcionalmente com um comentário # ao final.`}}},include:{term:{t:0,b:{t:2,i:[{t:3}],s:`[include]`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Uma diretiva que puxa outro arquivo de configuração para o printer.cfg, permitindo dividir as configurações entre arquivos.`}}},saveConfig:{term:{t:0,b:{t:2,i:[{t:3}],s:`SAVE_CONFIG`}},def:{t:0,b:{t:2,i:[{t:3}],s:`O bloco gerado automaticamente (após #*#) onde o Klipper armazena resultados de calibração - não edite à mão.`}}}}},file:{label:{t:0,b:{t:2,i:[{t:3}],s:`Arquivo de configuração`}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:`Selecione um arquivo…`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Atualizar`}},loadingList:{t:0,b:{t:2,i:[{t:3}],s:`Carregando arquivos…`}},emptyList:{t:0,b:{t:2,i:[{t:3}],s:`Nenhum arquivo de configuração encontrado na impressora.`}}},summary:{sections:{t:0,b:{t:2,i:[{t:4,k:`count`},{t:3,v:` seções`}]}},params:{t:0,b:{t:2,i:[{t:4,k:`count`},{t:3,v:` parâmetros`}]}},size:{t:0,b:{t:2,i:[{t:4,k:`kb`},{t:3,v:` KB`}]}}},validation:{title:{t:0,b:{t:2,i:[{t:3}],s:`Validação`}},clean:{t:0,b:{t:2,i:[{t:3}],s:`Nenhum problema estrutural encontrado.`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Erro`}},warning:{t:0,b:{t:2,i:[{t:3}],s:`Aviso`}}},view:{structured:{t:0,b:{t:2,i:[{t:3}],s:`Estruturado`}},raw:{t:0,b:{t:2,i:[{t:3}],s:`Bruto`}},expandAll:{t:0,b:{t:2,i:[{t:3}],s:`Expandir tudo`}},collapseAll:{t:0,b:{t:2,i:[{t:3}],s:`Recolher tudo`}}},section:{saveBadge:{t:0,b:{t:2,i:[{t:3}],s:`salvo automaticamente`}},noParams:{t:0,b:{t:2,i:[{t:3}],s:`(sem parâmetros)`}},paramsCount:{t:0,b:{t:2,i:[{t:4,k:`count`},{t:3,v:` parâmetros`}]}},paramHead:{t:0,b:{t:2,i:[{t:3}],s:`Parâmetro`}},valueHead:{t:0,b:{t:2,i:[{t:3}],s:`Valor`}}},edit:{hint:{t:0,b:{t:2,i:[{t:3}],s:`Edite o texto bruto abaixo e clique em Salvar. Um backup com data e hora é feito antes de qualquer gravação.`}}},save:{button:{t:0,b:{t:2,i:[{t:3}],s:`Salvar`}},saving:{t:0,b:{t:2,i:[{t:3}],s:`Salvando…`}},unsaved:{t:0,b:{t:2,i:[{t:3}],s:`Alterações não salvas`}},revert:{t:0,b:{t:2,i:[{t:3}],s:`Reverter`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`Salvar na impressora?`}},confirmBody:{t:0,b:{t:2,i:[{t:3,v:`Isso sobrescreve `},{t:4,k:`file`},{t:3,v:` na impressora. Um backup com data e hora é salvo antes, e é preciso reiniciar o firmware para aplicar a alteração.`}]}},ack:{t:0,b:{t:2,i:[{t:3}],s:`Entendo que isto grava na impressora`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Salvar`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Cancelar`}},done:{t:0,b:{t:2,i:[{t:3,v:`Salvo. Backup: `},{t:4,k:`backup`}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:`Recusado: a impressora está ocupada (imprimindo ou pausada). Tente novamente quando estiver ociosa.`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Falha ao salvar.`}},stale:{t:0,b:{t:2,i:[{t:3}],s:`O arquivo mudou no disco desde que foi carregado (um SAVE_CONFIG pode ter ocorrido, ou outro app o editou). Salvar agora sobrescreveria essa alteração - recarregue para revisar (a linha do tempo de backups mostra o que difere).`}},staleReload:{t:0,b:{t:2,i:[{t:3}],s:`Recarregar o arquivo`}}},restart:{prompt:{t:0,b:{t:2,i:[{t:3}],s:`Reiniciar o firmware para aplicar sua alteração?`}},button:{t:0,b:{t:2,i:[{t:3}],s:`Reiniciar firmware`}},restarting:{t:0,b:{t:2,i:[{t:3}],s:`Reiniciando…`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`Reiniciar firmware?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`O FIRMWARE_RESTART recarrega a configuração e interrompe a impressora brevemente. Faça isso apenas quando ela estiver ociosa.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Reiniciar agora`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Cancelar`}},done:{t:0,b:{t:2,i:[{t:3}],s:`Reinício do firmware solicitado.`}},busy:{t:0,b:{t:2,i:[{t:3}],s:`Recusado: a impressora está ocupada. Reinicie quando estiver ociosa.`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Falha ao reiniciar.`}}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Lendo a configuração…`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Não foi possível ler a configuração da impressora.`}},retry:{t:0,b:{t:2,i:[{t:3}],s:`Tentar novamente`}}},catalog:{title:{t:0,b:{t:2,i:[{t:3}],s:`Adicionar um bloco de configuração do catálogo`}},hint:{t:0,b:{t:2,i:[{t:3}],s:`Escolha uma peça - seu bloco do Klipper preciso quanto ao hardware (run_current, sense_resistor e nomes de pinos reais) é anexado ao arquivo para você revisar e salvar.`}},drivers:{t:0,b:{t:2,i:[{t:3}],s:`Drivers`}},motors:{t:0,b:{t:2,i:[{t:3}],s:`Motores`}},boards:{t:0,b:{t:2,i:[{t:3}],s:`Placas`}},pickPlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Buscar no catálogo…`}},inserted:{t:0,b:{t:2,i:[{t:3,v:`Bloco de `},{t:4,k:`name`},{t:3,v:` inserido - revise no modo Bruto e salve.`}]}},noSnippet:{t:0,b:{t:2,i:[{t:3,v:`Nenhum bloco de configuração disponível para `},{t:4,k:`name`},{t:3,v:`.`}]}}},drift:{title:{t:0,b:{t:2,i:[{t:3}],s:`O que o Klipper está executando`}},pending:{t:0,b:{t:2,i:[{t:3}],s:`O Klipper tem alterações não salvas (um SAVE_CONFIG está pendente) - salvar este arquivo agora as sobrescreveria. Execute SAVE_CONFIG no console primeiro.`}},warningsTitle:{t:0,b:{t:2,i:[{t:3}],s:`Avisos da configuração do Klipper`}},count:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` valor(es) no disco diferem do que está em execução (editados mas sem FIRMWARE_RESTART):`}]}},adopt:{t:0,b:{t:2,i:[{t:3}],s:`adotar ativo`}}},pinDoctor:{title:{t:0,b:{t:2,i:[{t:3,v:`Pin Doctor - `},{t:4,k:`n`},{t:3,v:` achado(s) de fiação`}]}},conflict:{t:0,b:{t:2,i:[{t:3}],s:`CONFLITO`}},caveat:{t:0,b:{t:2,i:[{t:3}],s:`RESSALVA`}}},tmc:{review:{t:0,b:{t:2,i:[{t:3}],s:`revisar no modo Bruto e salvar`}}},pinEdit:{offBoard:{t:0,b:{t:2,i:[{t:3}],s:`não está na placa`}},offBoardHint:{t:0,b:{t:2,i:[{t:3}],s:`Este pino não está no mapa de pinos conhecido da placa - verifique se há um erro de digitação ou um pino EXP/virtual.`}},double:{t:0,b:{t:2,i:[{t:3}],s:`reutilizado`}},doubleHint:{t:0,b:{t:2,i:[{t:3}],s:`Este pino está atribuído em mais de uma seção.`}},caveat:{t:0,b:{t:2,i:[{t:3}],s:`ressalva`}}},project:{title:{t:0,b:{t:2,i:[{t:3}],s:`Projeto (inclusões e busca)`}},lintBadge:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` problema(s)`}]}},searchPlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Buscar em todos os arquivos de configuração…`}},searchBtn:{t:0,b:{t:2,i:[{t:3}],s:`Buscar`}},noResults:{t:0,b:{t:2,i:[{t:3}],s:`Nenhuma correspondência.`}},matchesCount:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` correspondência(s)`}]}},truncated:{t:0,b:{t:2,i:[{t:3}],s:`exibindo os primeiros resultados`}},tree:{t:0,b:{t:2,i:[{t:3}],s:`Árvore de inclusões`}},missing:{t:0,b:{t:2,i:[{t:3}],s:`arquivo ausente`}},lint:{t:0,b:{t:2,i:[{t:3}],s:`Verificações entre arquivos`}},rule:{broken_include:{t:0,b:{t:2,i:[{t:3}],s:`Inclusão quebrada: `}},orphan_driver:{t:0,b:{t:2,i:[{t:3}],s:`Driver órfão - nenhuma seção correspondente: `}},section_override:{t:0,b:{t:2,i:[{t:3}],s:`Sobreposição (definida em vários arquivos, vale a última): `}}}},knowledge:{viewDriver:{t:0,b:{t:2,i:[{t:3,v:`Ver `},{t:4,k:`model`},{t:3,v:` no catálogo →`}]}},stepper:{t:0,b:{t:2,i:[{t:3}],s:`Um eixo de motor de passo - seus pinos de driver, distância de rotação, microsteps e homing/endstop.`}},tmc:{t:0,b:{t:2,i:[{t:3}],s:`Um driver de motor de passo Trinamic - corrente de operação/repouso, microsteps e ajuste de StallGuard/chopper para seu motor.`}},extruder:{t:0,b:{t:2,i:[{t:3}],s:`O hotend e o extrusor - tamanho do bico, caminho do filamento, aquecedor, termistor e PID.`}},heater_bed:{t:0,b:{t:2,i:[{t:3}],s:`A mesa aquecida - seu pino de aquecedor, termistor e limites de PID/temperatura.`}},fan:{t:0,b:{t:2,i:[{t:3}],s:`A ventoinha de resfriamento de peça que esfria o filamento recém-impresso.`}},heater_fan:{t:0,b:{t:2,i:[{t:3}],s:`Uma ventoinha ligada a um aquecedor (ex.: resfriamento do hotend) que funciona para protegê-lo do superaquecimento.`}},controller_fan:{t:0,b:{t:2,i:[{t:3}],s:`Uma ventoinha que resfria os drivers dos motores / a eletrônica enquanto os motores estão ativos.`}},mcu:{t:0,b:{t:2,i:[{t:3}],s:`Uma placa microcontroladora rodando o Klipper - sua conexão serial ou CAN.`}},printer:{t:0,b:{t:2,i:[{t:3}],s:`Cinemática global da máquina e limites de movimento (tipo, velocidade máxima, aceleração).`}},bed_mesh:{t:0,b:{t:2,i:[{t:3}],s:`Nivelamento automático da mesa - sonda uma grade e compensa a planicidade da mesa durante a impressão.`}},probe:{t:0,b:{t:2,i:[{t:3}],s:`A sonda Z usada para detectar a superfície da mesa no homing e no bed mesh.`}},gcode_macro:{t:0,b:{t:2,i:[{t:3}],s:`Uma macro de G-code personalizada - um comando nomeado chamável pelo console ou por outras macros.`}},output_pin:{t:0,b:{t:2,i:[{t:3}],s:`Um pino de saída controlável (um LED, relé ou linha de habilitação, por exemplo).`}},neopixel:{t:0,b:{t:2,i:[{t:3}],s:`LEDs RGB endereçáveis (NeoPixel / WS2812) e seu controle de cor.`}},board_pins:{t:0,b:{t:2,i:[{t:3}],s:`Apelidos amigáveis para os pinos físicos de uma placa, referenciados em outras partes da configuração.`}},input_shaper:{t:0,b:{t:2,i:[{t:3}],s:`Compensação de ressonância que reduz ringing e fantasmas (ghosting) em velocidades mais altas.`}},safe_z_home:{t:0,b:{t:2,i:[{t:3}],s:`Faz o homing do Z em uma posição XY segura (geralmente o centro da mesa) para proteger o bico e a mesa.`}},z_tilt:{t:0,b:{t:2,i:[{t:3}],s:`Ajusta vários motores Z para que o plano do pórtico/mesa fique nivelado.`}},quad_gantry_level:{t:0,b:{t:2,i:[{t:3}],s:`Nivela um pórtico de quatro pontos para que fique paralelo à mesa.`}},filament_switch_sensor:{t:0,b:{t:2,i:[{t:3}],s:`Um sensor de fim de filamento que pausa a impressão quando o filamento acaba.`}},virtual_sdcard:{t:0,b:{t:2,i:[{t:3}],s:`Permite ao Klipper imprimir arquivos enviados ao host (necessário para Mainsail e Fluidd).`}}},backups:{title:{t:0,b:{t:2,i:[{t:3,v:`Backups (`},{t:4,k:`n`},{t:3,v:`)`}]}},diff:{t:0,b:{t:2,i:[{t:3}],s:`Diferença`}},hideDiff:{t:0,b:{t:2,i:[{t:3}],s:`Ocultar diferença`}},restore:{t:0,b:{t:2,i:[{t:3}],s:`Restaurar`}},diffHint:{t:0,b:{t:2,i:[{t:3}],s:`diferença em relação ao arquivo atual`}},unchanged:{t:0,b:{t:2,i:[{t:3,v:`⋯ `},{t:4,k:`n`},{t:3,v:` linhas inalteradas ⋯`}]}},note:{t:0,b:{t:2,i:[{t:3}],s:`Os snapshots são gravados automaticamente antes de cada gravação. Restaurar carrega um deles no editor para uma revisão final + gravação.`}}},sanity:{title:{t:0,b:{t:2,i:[{t:3,v:`Verificação de valores do driver (`},{t:4,k:`n`},{t:3,v:`)`}]}},note:{t:0,b:{t:2,i:[{t:3,v:`Verificadas `},{t:4,k:`n`},{t:3,v:` seção(ões) de driver TMC. Um driver sem teto curado e um motor de passo sem motor atribuído são ignorados, não chutados.`}]}},rule:{over_driver_cap:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current de `},{t:4,k:`run_current`},{t:3,v:` A excede o teto de fundo de escala de ~`},{t:4,k:`cap`},{t:3,v:` A do driver.`}]}},near_driver_cap:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current de `},{t:4,k:`run_current`},{t:3,v:` A está dentro de 10% do teto de ~`},{t:4,k:`cap`},{t:3,v:` A do driver.`}]}},over_motor_rating:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current de `},{t:4,k:`run_current`},{t:3,v:` A excede a especificação do `},{t:4,k:`motor`},{t:3,v:` (`},{t:4,k:`max_current`},{t:3,v:` A).`}]}},near_motor_rating:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current de `},{t:4,k:`run_current`},{t:3,v:` A está dentro de 10% da especificação do `},{t:4,k:`motor`},{t:3,v:` (`},{t:4,k:`max_current`},{t:3,v:` A).`}]}},odd_microsteps:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: microsteps `},{t:4,k:`microsteps`},{t:3,v:` não é uma potência de dois (1…256).`}]}}}},panels:{failed:{t:0,b:{t:2,i:[{t:3,v:`Alguns painéis não puderam carregar e estão ocultos: `},{t:4,k:`panels`},{t:3,v:`. O que eles verificariam é desconhecido neste momento - não necessariamente está tudo bem.`}]}},name:{drift:{t:0,b:{t:2,i:[{t:3}],s:`Disco-vs-ativo`}},pinDoctor:{t:0,b:{t:2,i:[{t:3}],s:`Pin Doctor`}},sanity:{t:0,b:{t:2,i:[{t:3}],s:`Verificação do driver`}},project:{t:0,b:{t:2,i:[{t:3}],s:`Visão do projeto`}},pinMap:{t:0,b:{t:2,i:[{t:3}],s:`Sugestões de pinos`}},backups:{t:0,b:{t:2,i:[{t:3}],s:`Backups`}},lint:{t:0,b:{t:2,i:[{t:3}],s:`Verificação da config`}}}},addPart:{title:{t:0,b:{t:2,i:[{t:3}],s:`Adicionar uma peça (ciente de pinos livres)`}},hint:{t:0,b:{t:2,i:[{t:3}],s:`Escolha um tipo de peça e um dos pinos da placa que NADA usa ainda (lidos ao vivo da sua configuração + mapa da placa), e obtenha uma seção pronta gravada pela trava de segurança - sem chutar pinos.`}},kind:{t:0,b:{t:2,i:[{t:3}],s:`Tipo de peça`}},name:{t:0,b:{t:2,i:[{t:3}],s:`Nome`}},namePh:{t:0,b:{t:2,i:[{t:3}],s:`ex.: chamber_fan`}},mcu:{t:0,b:{t:2,i:[{t:3}],s:`Placa (MCU)`}},pin:{t:0,b:{t:2,i:[{t:3}],s:`Pino livre`}},pinPh:{t:0,b:{t:2,i:[{t:3}],s:`Escolha um pino livre…`}},noFree:{t:0,b:{t:2,i:[{t:3}],s:`Nenhum pino nomeado livre neste mapa de placa.`}}},lint:{title:{t:0,b:{t:2,i:[{t:3,v:`Verificação da config — `},{t:4,k:`n`},{t:3,v:` ocorrência(s)`}]}},note:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` seções verificadas. Apenas checagens estruturais; usa os próprios avisos de config do Klipper.`}]}},rule:{double_assigned_pin:{t:0,b:{t:2,i:[{t:3,v:`O pin `},{t:4,k:`pin`},{t:3,v:` está atribuído em várias seções (`},{t:4,k:`sections`},{t:3,v:`). Um firmware restart vai falhar.`}]}},pin_caveat:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: pin `},{t:4,k:`pin`},{t:3,v:` — `},{t:4,k:`message`}]}},klipper_warning:{t:0,b:{t:2,i:[{t:3,v:`Klipper: `},{t:4,k:`message`}]}},missing_printer:{t:0,b:{t:2,i:[{t:3}],s:`Nenhuma seção [printer] encontrada — o Klipper não inicia sem ela.`}},no_stepper:{t:0,b:{t:2,i:[{t:3}],s:`Nenhuma seção stepper ou extruder encontrada.`}},heater_temp_range:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: min_temp (`},{t:4,k:`min_temp`},{t:3,v:`) não está abaixo de max_temp (`},{t:4,k:`max_temp`},{t:3,v:`).`}]}}}}}};export{e as default};